{
 "id": "rules-line-length",
 "severity": "advisory",
 "failureMessage": "a rule changed one word at a time still shows as a whole-paragraph diff when its bullet is one physical line",
 "scanFiles": "/(^|\\/)RULES\\.md$/",
 "maxLineLength": {
  "bytes": 100,
  "what": "{count} line(s) over {bytes} bytes, longest {longest}",
  "fix": "wrap the prose at {bytes} columns \u2014 a Markdown bullet continues on an indented line, so the rendering is unchanged"
 }
}
---

